def get_different_subcloud(subclouds: List[Subcloud], subclouds_to_exclude: Optional[List[Subcloud]] = None, subcloud_names_to_exclude: Optional[List[str]] = None) -> Subcloud:
    if subclouds_to_exclude is None:
        subclouds_to_exclude = []
    if subcloud_names_to_exclude is None:
        subcloud_names_to_exclude = []

    remaining_subclouds = [subcloud for subcloud in subclouds if subcloud not in subclouds_to_exclude and subcloud.get_name() not in subcloud_names_to_exclude]

    if not remaining_subclouds:
        raise ValueError("No different subclouds available to exclude.")

    highest_subcloud = max(remaining_subclouds, key=lambda subcloud: int(subcloud.get_id()))
    return highest_subcloud
