def wait_for_vim_ready(self, max_attempts=10):
    for attempt in range(max_attempts):
        if self.is_sm_service_up():
            try:
                response = self.send_request_to_vim_api()
                if response.status_code == 200:
                    return True
            except Exception as e:
                self.log.error(f"Failed to get response from vim-api: {e}")
        time.sleep(1)
    return False

def is_sm_service_up(self):
    # Check if the SM service is up by querying its PID
    pid = self.get_sm_service_pid()
    return pid is not None

def send_request_to_vim_api(self):
    # Send a request to the vim-api and return the response
    url = "http://localhost:8080/vim-api"
    response = requests.get(url)
    return response
